<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>{{ $title ?? 'Client Portal Admin' }}</title><style>
:root{--bg:#0d1117;--surface:#161b22;--surface2:#1c2128;--muted:#8b949e;--text:#e6edf3;--accent:#2f81f7;--danger:#da3633;--success:#3fb950;--border:#30363d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{height:60px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;background:rgba(13,17,23,.96);z-index:10}.brand{font-weight:700;color:var(--text);text-decoration:none}.nav{display:flex;gap:8px}.wrap{max-width:1240px;margin:0 auto;padding:28px 20px 80px}.heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px}h1{font-size:28px;margin:0}h2{font-size:18px;margin:0 0 16px}h3{font-size:15px;margin:0}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:14px}.panel{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:18px}.section{margin-top:30px}.row{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--border)}.row:last-child{border-bottom:0}.button{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:0 12px;border:1px solid var(--border);border-radius:6px;background:transparent;color:var(--text);text-decoration:none;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.button.primary{background:var(--accent);border-color:var(--accent)}.button.danger{border-color:var(--danger);color:#ff938f}.field{margin-bottom:12px}label{display:block;color:var(--muted);font-size:11px;font-weight:700;text-transform:uppercase;margin-bottom:6px}input,textarea,select{width:100%;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);padding:9px 10px;font:inherit;font-size:14px}textarea{min-height:110px;resize:vertical}.checks{display:flex;gap:18px}.checks label{display:flex;align-items:center;gap:7px;text-transform:none;color:var(--text)}.checks input{width:auto}.flash,.errors{padding:12px 14px;border:1px solid rgba(47,129,247,.5);background:rgba(47,129,247,.12);border-radius:7px;margin-bottom:18px}.errors{border-color:var(--danger);background:rgba(218,54,51,.1)}.badge{font-size:10px;text-transform:uppercase;border:1px solid var(--border);border-radius:20px;padding:4px 7px}.actions{display:flex;flex-wrap:wrap;gap:7px}.diff{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;line-height:1.55;white-space:pre-wrap}.diff-line{display:block;padding:1px 8px}.diff-line.added{background:rgba(46,160,67,.2);color:#aff5b4}.diff-line.removed{background:rgba(248,81,73,.18);color:#ffdcd7}.diff-line.same{color:var(--muted)}@media(max-width:700px){.top{padding:0 14px}.wrap{padding:22px 14px}.nav .secondary{display:none}.heading{align-items:start;flex-direction:column}}
</style></head><body><header class="top"><a class="brand" href="{{ route('admin.client-portal.index') }}">Studio Kristian / Client Portal</a><nav class="nav"><a class="button secondary" href="{{ route('admin.portfolio.index') }}">Portfolio</a><form method="POST" action="{{ route('logout') }}">@csrf<button class="button" type="submit">Log out</button></form></nav></header><main class="wrap">@if(session('status'))<div class="flash">{{ session('status') }}</div>@endif @if($errors->any())<div class="errors">{{ $errors->first() }}</div>@endif @yield('content')</main></body></html>